import re
KV = re.compile(r"^(?P<key>_?kMDItem\w+)\s+= (?P<value>.*?)\s*$")
OPEN = re.compile(r"^\($")
ITEM = re.compile(r"^\s+(?P<item>.*?),?\s*$")
CLOSE = re.compile(r"^\)\s*$")

def unquote(v):
    if len(v) >= 2 and v[0] == v[-1] == "\"":
        return v[1:-1]
    return v

def parse(lines):
    rec, used = {}, []
    key, items = None, None
    for j, ln in enumerate(lines):
        if not ln.strip():
            continue
        if key is not None:
            # inside a ( ... ) list: items until the closer, joined with ;
            if CLOSE.match(ln):
                rec[key] = ";".join(items)
                key, items = None, None
            else:
                m = ITEM.match(ln)
                items.append(unquote(m.group("item")) if m else ln.strip())
            used.append(j)
            continue
        m = KV.match(ln)
        if not m:
            continue
        used.append(j)
        if OPEN.match(m.group("value")):
            key, items = m.group("key"), []
            rec[key] = ""
        else:
            rec[m.group("key")] = unquote(m.group("value"))
    return {"blocks": [{"name": "attributes", "kind": "kv", "lines": used, "records": [rec]}],
            "skip": []}
